const width = 960;
const height = 500;
const margin = { top: 40, right: 40, bottom: 60, left: 40 };

const svg = d3.select("body")
  .append("svg")
  .attr("width", width)
  .attr("height", height)
  .attr("viewBox", `0 0 ${width} ${height}`)
  .style("background", "#f8f9fa")
  .style("font-family", "system-ui, -apple-system, sans-serif");

const defs = svg.append("defs");

const gradient = defs.append("linearGradient")
  .attr("id", "node-gradient")
  .attr("x1", "0%")
  .attr("y1", "0%")
  .attr("x2", "0%")
  .attr("y2", "100%");

gradient.append("stop").attr("offset", "0%").attr("stop-color", "#ffffff");
gradient.append("stop").attr("offset", "100%").attr("stop-color", "#e9ecef");

defs.append("marker")
  .attr("id", "arrow")
  .attr("viewBox", "0 -5 10 10")
  .attr("refX", 8)
  .attr("refY", 0)
  .attr("markerWidth", 6)
  .attr("markerHeight", 6)
  .attr("orient", "auto")
  .append("path")
  .attr("d", "M0,-5L10,0L0,5")
  .attr("fill", "#495057");

const g = svg.append("g")
  .attr("transform", `translate(${margin.left}, ${margin.top})`);

const innerWidth = width - margin.left - margin.right;
const innerHeight = height - margin.top - margin.bottom;

const clientX = innerWidth * 0.2;
const serverX = innerWidth * 0.8;
const centerY = innerHeight * 0.4;

const clientGroup = g.append("g").attr("class", "client-node");
const serverGroup = g.append("g").attr("class", "server-node");

clientGroup.append("rect")
  .attr("x", clientX - 60)
  .attr("y", centerY - 40)
  .attr("width", 120)
  .attr("height", 80)
  .attr("rx", 8)
  .attr("fill", "url(#node-gradient)")
  .attr("stroke", "#dee2e6")
  .attr("stroke-width", 2)
  .attr("class", "client-box");

clientGroup.append("text")
  .attr("x", clientX)
  .attr("y", centerY - 10)
  .attr("text-anchor", "middle")
  .attr("font-size", "14px")
  .attr("font-weight", "600")
  .attr("fill", "#212529")
  .text("WebSocket Client");

clientGroup.append("text")
  .attr("x", clientX)
  .attr("y", centerY + 15)
  .attr("text-anchor", "middle")
  .attr("font-size", "12px")
  .attr("fill", "#6c757d")
  .attr("class", "client-status")
  .text("Idle");

serverGroup.append("rect")
  .attr("x", serverX - 60)
  .attr("y", centerY - 40)
  .attr("width", 120)
  .attr("height", 80)
  .attr("rx", 8)
  .attr("fill", "url(#node-gradient)")
  .attr("stroke", "#dee2e6")
  .attr("stroke-width", 2)
  .attr("class", "server-box");

serverGroup.append("text")
  .attr("x", serverX)
  .attr("y", centerY - 10)
  .attr("text-anchor", "middle")
  .attr("font-size", "14px")
  .attr("font-weight", "600")
  .attr("fill", "#212529")
  .text("WebSocket Server");

serverGroup.append("text")
  .attr("x", serverX)
  .attr("y", centerY + 15)
  .attr("text-anchor", "middle")
  .attr("font-size", "12px")
  .attr("fill", "#6c757d")
  .attr("class", "server-status")
  .text("Listening");

const connectionLine = g.append("line")
  .attr("x1", clientX + 60)
  .attr("y1", centerY)
  .attr("x2", serverX - 60)
  .attr("y2", centerY)
  .attr("stroke", "#dee2e6")
  .attr("stroke-width", 2)
  .attr("stroke-dasharray", "5,5");

const eventLog = g.append("g")
  .attr("transform", `translate(${innerWidth / 2}, ${innerHeight - 80})`);

const eventText = eventLog.append("text")
  .attr("text-anchor", "middle")
  .attr("font-size", "14px")
  .attr("font-weight", "500")
  .attr("fill", "#495057");

const timeline = [
  { 
    action: "connecting",
    text: "Event: connecting...",
    duration: 1500,
    update: () => {
      d3.select(".client-status").text("Connecting...");
      d3.select(".client-box").transition().duration(300).attr("stroke", "#ffc107");
      connectionLine.transition().duration(500).attr("stroke", "#ffc107");
    }
  },
  { 
    action: "open",
    text: "Event: open - Connection established",
    duration: 2000,
    update: () => {
      d3.select(".client-status").text("Connected");
      d3.select(".server-status").text("Connected");
      d3.select(".client-box").transition().duration(300).attr("stroke", "#28a745");
      d3.select(".server-box").transition().duration(300).attr("stroke", "#28a745");
      connectionLine.transition().duration(300).attr("stroke", "#28a745").attr("stroke-dasharray", null);
    }
  },
  { 
    action: "send",
    text: "Event: message (Client → Server)",
    duration: 2000,
    update: () => {
      const packet = g.append("circle")
        .attr("cx", clientX + 60)
        .attr("cy", centerY)
        .attr("r", 6)
        .attr("fill", "#007bff");

      packet.transition()
        .duration(1000)
        .ease(d3.easeCubicInOut)
        .attr("cx", serverX - 60)
        .on("end", function() {
          d3.select(this).remove();
          d3.select(".server-box")
            .transition().duration(100).attr("fill", "#cce5ff")
            .transition().duration(300).attr("fill", "url(#node-gradient)");
        });
    }
  },
  { 
    action: "receive",
    text: "Event: message (Server → Client)",
    duration: 2000,
    update: () => {
      const packet = g.append("circle")
        .attr("cx", serverX - 60)
        .attr("cy", centerY)
        .attr("r", 6)
        .attr("fill", "#dc3545");

      packet.transition()
        .duration(1000)
        .ease(d3.easeCubicInOut)
        .attr("cx", clientX + 60)
        .on("end", function() {
          d3.select(this).remove();
          d3.select(".client-box")
            .transition().duration(100).attr("fill", "#f8d7da")
            .transition().duration(300).attr("fill", "url(#node-gradient)");
        });
    }
  },
  { 
    action: "close",
    text: "Event: close - Connection terminated",
    duration: 2000,
    update: () => {
      d3.select(".client-status").text("Closed");
      d3.select(".server-status").text("Listening");
      d3.select(".client-box").transition().duration(300).attr("stroke", "#6c757d");
      d3.select(".server-box").transition().duration(300).attr("stroke", "#dee2e6");
      connectionLine.transition().duration(300).attr("stroke", "#dee2e6").attr("stroke-dasharray", "5,5");
    }
  }
];

let currentIndex = 0;

function runSequence() {
  if (currentIndex >= timeline.length) {
    currentIndex = 0;
    setTimeout(runSequence, 1000);
    return;
  }

  const step = timeline[currentIndex];

  eventText.transition()
    .duration(300)
    .style("opacity", 0)
    .on("end", function() {
      d3.select(this).text(step.text).transition().duration(300).style("opacity", 1);
    });

  step.update();

  currentIndex++;
  setTimeout(runSequence, step.duration);
}

const title = svg.append("text")
  .attr("x", width / 2)
  .attr("y", 30)
  .attr("text-anchor", "middle")
  .attr("font-size", "18px")
  .attr("font-weight", "600")
  .attr("fill", "#212529")
  .text("WebSocket Runtime Event Flow");

setTimeout(runSequence, 500);

